import json
import csv

def get_max_cvss(cvss_data):
    if not cvss_data:
        return "N/A"
    scores = []
    for source, data in cvss_data.items():
        if "V3Score" in data:
            scores.append(data["V3Score"])
        elif "V2Score" in data:
            scores.append(data["V2Score"])
    return max(scores) if scores else "N/A"

def main():
    with open('/root/trivy_report.json', 'r') as f:
        report = json.load(f)

    vulnerabilities = []
    if "Results" in report:
        for result in report["Results"]:
            if "Vulnerabilities" in result:
                for vuln in result["Vulnerabilities"]:
                    package = vuln.get("PkgName", "N/A")
                    version = vuln.get("InstalledVersion", "N/A")
                    cve_id = vuln.get("VulnerabilityID", "N/A")
                    severity = vuln.get("Severity", "N/A")
                    cvss_score = get_max_cvss(vuln.get("CVSS"))
                    fixed_version = vuln.get("FixedVersion", "N/A")
                    title = vuln.get("Title", vuln.get("Description", "N/A")).split('\n')[0]
                    url = vuln.get("PrimaryURL", "N/A")

                    vulnerabilities.append([
                        package, version, cve_id, severity, cvss_score, fixed_version, title, url
                    ])

    with open('/root/security_audit.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(["Package", "Version", "CVE_ID", "Severity", "CVSS_Score", "Fixed_Version", "Title", "Url"])
        writer.writerows(vulnerabilities)

if __name__ == "__main__":
    main()

